def longest(a: list[int], b: list[int]) -> list[int]:
    """Return the longer of a and b; if they have equal length, return a."""
    return b if len(b) > len(a) else a


def test_longest_first_is_longer() -> None:
    assert longest([1, 2, 3], [4]) == [1, 2, 3]


def test_longest_second_is_longer() -> None:
    assert longest([9], [4, 5, 6]) == [4, 5, 6]


def test_longest_tie_returns_first() -> None:
    a = [1, 2]
    b = [3, 4]
    assert longest(a, b) is a


def test_longest_both_empty() -> None:
    assert longest([], []) == []


def test_longest_one_empty() -> None:
    assert longest([], [7]) == [7]
    assert longest([7], []) == [7]
